  );
state.signedCopy = action.input.file
  ? checkedFile(action.input.file)
  : null;

operations.schema:
input WithdrawProposalInput {
  reason: String!
}

operations.reducer:
if (!["DRAFT", "APPROVED", "SENT"].includes(state.status))
  throw new ProposalFinalError(
    "An accepted, declined, withdrawn or superseded proposal cannot be withdrawn",
  );
if (action.input.reason.trim() === "")
  throw new WithdrawReasonRequiredError(
    "Withdrawing a proposal needs a reason",
  );
state.status = "WITHDRAWN";
state.reason = action.input.reason;

operations.schema:
input SupersedeProposalInput {
  supersededByProposalId: PHID!
}

operations.reducer:
if (state.status !== "SENT" && state.status !== "DECLINED")
  throw new ProposalNotSupersedableError(
    "Only a sent or declined proposal can be superseded",
  );
if (action.input.supersededByProposalId.trim() === "")
  throw new ReplacementRequiredError(
    "Superseding a proposal needs the proposal that replaces it",
  );
state.status = "SUPERSEDED";
state.supersededByProposalId = action.input.supersededByProposalId;

operations.schema:
input AddReferenceInput {
  id: OID!
  kind: ReferenceKind!
  documentId: PHID!
  title: String!
}

operations.reducer:
const { id, kind, documentId, title } = action.input;
if (state.status !== "DRAFT")
  throw new ProposalNotDraftError("Only a draft proposal can be edited");
if (state.references.some((reference) => reference.id === id))
  throw new DuplicateReferenceIdError(`Reference ${id} already exists`);
{
  const existing = state.references.find(
    (reference) =>
      reference.documentId === documentId && reference.kind === kind,
  );
  if (existing)
    throw new DuplicateReferenceError(
      `"${existing.title}" is already linked.`,
    );
}
state.references.push({ id, kind, documentId, title });

operations.schema:
input RemoveReferenceInput {
  id: OID!
}

operations.reducer:
if (state.status !== "DRAFT")
  throw new ProposalNotDraftError("Only a draft proposal can be edited");
const index = state.references.findIndex(
  (reference) => reference.id === action.input.id,
);
if (index === -1)
  throw new ReferenceNotFoundError(
    `Reference ${action.input.id} not found`,
  );
state.references.splice(index, 1);

const { id, code, name, summary, requires, price, currency, targetDate } =
  action.input;
if (state.status !== "DRAFT")
  throw new ProposalNotDraftError("Only a draft proposal can be edited");
if (state.packages.some((pkg) => pkg.id === id))
  throw new DuplicatePackageIdError(`Package ${id} already exists`);
if (state.packages.some((pkg) => pkg.code === code))
  throw new DuplicatePackageCodeError(
    `Package code ${code} is already used`,
  );
const required = requires ?? [];
for (const requiredId of required) {
  if (requiredId === id)
    throw new PackageRequiresItselfError("A package cannot require itself");
  if (!state.packages.some((pkg) => pkg.id === requiredId))
    throw new UnknownRequiredPackageError(
      `Required package ${requiredId} not found`,
    );
}
checkAmountCurrency(state, [price], currency);
state.packages.push({
  id,
  code,
  name,
  summary: summary ?? null,
  requires: required,
  price: price ?? null,
  targetDate: targetDate ?? null,
});

const input = action.input;
if (state.status !== "DRAFT")
  throw new ProposalNotDraftError("Only a draft proposal can be edited");
const pkg = state.packages.find((item) => item.id === input.id);
if (!pkg) throw new PackageNotFoundError(`Package ${input.id} not found`);
if (
  input.code != null &&
  state.packages.some((p) => p.id !== pkg.id && p.code === input.code)
)
  throw new DuplicatePackageCodeError(
    `Package code ${input.code} is already used`,
  );
for (const requiredId of input.requires ?? []) {
  if (requiredId === pkg.id)
    throw new PackageRequiresItselfError("A package cannot require itself");
  if (!state.packages.some((p) => p.id === requiredId))
    throw new UnknownRequiredPackageError(
      `Required package ${requiredId} not found`,
    );
}
if (input.price != null) {
  checkAmountCurrency(state, [input.price], input.currency);
  if (
    state.deliverables.some(
      (d) => d.packageId === pkg.id && d.price?.pricing === "FIXED",
    )
  )
    throw new PackagePricedTwiceError(
      `Package ${pkg.id} has fixed-price deliverables, so it cannot have a price of its own`,
    );
}
if (input.code != null) pkg.code = input.code;
if (input.name != null) pkg.name = input.name;
if (input.summary !== undefined) pkg.summary = input.summary;
if (input.requires != null) pkg.requires = input.requires;
if (input.price !== undefined) pkg.price = input.price;
if (input.targetDate !== undefined) pkg.targetDate = input.targetDate;

operations.schema:
input RemovePackageInput {
  id: OID!
}

operations.reducer:
const { id } = action.input;
if (state.status !== "DRAFT")
  throw new ProposalNotDraftError("Only a draft proposal can be edited");
const index = state.packages.findIndex((pkg) => pkg.id === id);
if (index === -1) throw new PackageNotFoundError(`Package ${id} not found`);
if (
  state.deliverables.some((d) => d.packageId === id) ||
  state.options.some((o) => o.packageIds.includes(id)) ||
  state.packages.some((p) => p.requires.includes(id)) ||
  state.useCases.some((u) => u.packageId === id) ||
  state.boundaries.some((b) => b.packageId === id)
)
  throw new PackageInUseError(
    `Package ${id} is still used by a deliverable, an option or another package`,
  );
state.packages.splice(index, 1);

operations.schema:
input ReorderPackagesInput {
  ids: [OID!]!
}

operations.reducer:
if (state.status !== "DRAFT")
  throw new ProposalNotDraftError("Only a draft proposal can be edited");
const { ids } = action.input;
checkPermutation(state.packages, ids, () => {
  throw new PackageOrderMismatchError(
    "The new order must list every package exactly once",
  );
});
state.packages = ids.map((id) =>
  state.packages.find((pkg) => pkg.id === id)!,
);

const { id, code, packageId, title, body } = action.input;
if (state.status !== "DRAFT")
  throw new ProposalNotDraftError("Only a draft proposal can be edited");
if (state.deliverables.some((d) => d.id === id))
  throw new DuplicateDeliverableIdError(`Deliverable ${id} already exists`);
if (state.deliverables.some((d) => d.code === code))
  throw new DuplicateDeliverableCodeError(
    `Deliverable code ${code} is already used`,
  );
if (!state.packages.some((p) => p.id === packageId))
  throw new PackageNotFoundError(`Package ${packageId} not found`);
state.deliverables.push({
  id,
  code,
  packageId,
  title,
  body: body ?? null,
  price: null,
});

const input = action.input;
if (state.status !== "DRAFT")
  throw new ProposalNotDraftError("Only a draft proposal can be edited");
const deliverable = state.deliverables.find((d) => d.id === input.id);
if (!deliverable)
  throw new DeliverableNotFoundError(`Deliverable ${input.id} not found`);
if (
  input.code != null &&
  state.deliverables.some((d) => d.id !== input.id && d.code === input.code)
)
  throw new DuplicateDeliverableCodeError(
    `Deliverable code ${input.code} is already used`,
  );
if (input.packageId != null) {
  const target = state.packages.find((p) => p.id === input.packageId);
  if (!target)
    throw new PackageNotFoundError(`Package ${input.packageId} not found`);
  if (target.price != null && deliverable.price?.pricing === "FIXED")
    throw new PackagePricedTwiceError(
      `Package ${target.id} has its own price, so it cannot have a fixed-price deliverable`,
    );
  deliverable.packageId = input.packageId;
}
if (input.code != null) deliverable.code = input.code;
if (input.title != null) deliverable.title = input.title;
if (input.body !== undefined) deliverable.body = input.body;

const input = action.input;
if (state.status !== "DRAFT")
  throw new ProposalNotDraftError("Only a draft proposal can be edited");
const deliverable = state.deliverables.find((d) => d.id === input.id);
if (!deliverable)
  throw new DeliverableNotFoundError(`Deliverable ${input.id} not found`);
const { pricing, amount, upperAmount } = input;
if (pricing === "INCLUDED") {
  if (amount != null || upperAmount != null)
    throw new IncludedHasNoAmountError(
      "An included deliverable has no amount",
    );
} else {
  if (amount == null)
    throw new AmountRequiredError(
      `${{ FIXED: "A fixed price", RECURRING: "A recurring price", RATE: "A rate" }[pricing]} needs an amount`,
    );
  if (pricing === "RECURRING" && input.period == null)
    throw new PeriodRequiredError("A recurring price needs a period");
  if (pricing === "RATE" && input.unit == null)
    throw new UnitRequiredError("A rate needs a unit");
  if (upperAmount != null && upperAmount < amount)
    throw new UpperAmountBelowAmountError(
      "The upper amount cannot be below the amount",
    );
}
checkAmountCurrency(state, [amount, upperAmount], input.currency);
const target = state.packages.find((p) => p.id === deliverable.packageId);
if (pricing === "FIXED" && target?.price != null)
  throw new PackagePricedTwiceError(
    `Package ${target.id} has its own price, so it cannot have a fixed-price deliverable`,
  );
deliverable.price = {
  pricing,
  amount: amount ?? null,
  upperAmount: upperAmount ?? null,
  period: pricing === "RECURRING" ? input.period! : null,
  unit: pricing === "RATE" ? input.unit! : null,
  until: pricing === "RECURRING" ? (input.until ?? null) : null,
  note: input.note ?? null,
};

operations.schema:
input RemoveDeliverableInput {
  id: OID!
}

operations.reducer:
if (state.status !== "DRAFT")
  throw new ProposalNotDraftError("Only a draft proposal can be edited");
const index = state.deliverables.findIndex((d) => d.id === action.input.id);
if (index === -1)
  throw new DeliverableNotFoundError(
    `Deliverable ${action.input.id} not found`,
  );
state.deliverables.splice(index, 1);

operations.schema:
input ReorderDeliverablesInput {
  ids: [OID!]!
}

operations.reducer:
if (state.status !== "DRAFT")
  throw new ProposalNotDraftError("Only a draft proposal can be edited");
const { ids } = action.input;
checkPermutation(state.deliverables, ids, () => {
  throw new DeliverableOrderMismatchError(
    "The new order must list every deliverable exactly once",
  );
});
state.deliverables = ids.map((id) =>
  state.deliverables.find((d) => d.id === id)!,
);

operations.schema:
input AddOptionInput {
  id: OID!
  label: String!
  packageIds: [OID!]!
}

operations.reducer:
const { id, label, packageIds } = action.input;
if (state.status !== "DRAFT")
  throw new ProposalNotDraftError("Only a draft proposal can be edited");
if (state.options.some((o) => o.id === id))
  throw new DuplicateOptionIdError(`Option ${id} already exists`);
checkPackages(state.packages, packageIds);
state.options.push({ id, label, packageIds, adjustments: [] });

operations.schema:
input UpdateOptionInput {
  id: OID!
  label: String
  packageIds: [OID!]
}

operations.reducer:
const { id, label, packageIds } = action.input;
if (state.status !== "DRAFT")
  throw new ProposalNotDraftError("Only a draft proposal can be edited");
const option = state.options.find((o) => o.id === id);
if (!option) throw new OptionNotFoundError(`Option ${id} not found`);
if (packageIds != null) checkPackages(state.packages, packageIds);
if (label != null) option.label = label;
if (packageIds != null) option.packageIds = packageIds;

operations.schema:
input RemoveOptionInput {
  id: OID!
}

operations.reducer:
const { id } = action.input;
if (state.status !== "DRAFT")
  throw new ProposalNotDraftError("Only a draft proposal can be edited");
const index = state.options.findIndex((o) => o.id === id);
if (index === -1) throw new OptionNotFoundError(`Option ${id} not found`);
state.options.splice(index, 1);

const { optionId, id, label, amount, currency, condition } = action.input;
if (state.status !== "DRAFT")
  throw new ProposalNotDraftError("Only a draft proposal can be edited");
const option = state.options.find((o) => o.id === optionId);
if (!option) throw new OptionNotFoundError(`Option ${optionId} not found`);
if (state.options.some((o) => o.adjustments.some((a) => a.id === id)))
  throw new DuplicateAdjustmentIdError(`Adjustment ${id} already exists`);
checkAmountCurrency(state, [amount], currency);
option.adjustments.push({
  id,
  label,
  amount,
  condition: condition ?? null,
});

operations.schema:
input RemoveAdjustmentInput {
  optionId: OID!
  id: OID!
}

operations.reducer:
const { optionId, id } = action.input;
if (state.status !== "DRAFT")
  throw new ProposalNotDraftError("Only a draft proposal can be edited");
const option = state.options.find((o) => o.id === optionId);
if (!option) throw new OptionNotFoundError(`Option ${optionId} not found`);
const index = option.adjustments.findIndex((a) => a.id === id);
if (index === -1)
  throw new AdjustmentNotFoundError(
    `Adjustment ${id} not found in option ${optionId}`,
  );
option.adjustments.splice(index, 1);

const { id, label, trigger, percentage, date } = action.input;
if (state.status !== "DRAFT")
  throw new ProposalNotDraftError("Only a draft proposal can be edited");
if (state.paymentSteps.some((s) => s.id === id))
  throw new DuplicatePaymentStepIdError(
    `Payment step ${id} already exists`,
  );
checkStep(percentage, trigger, date ?? null);
state.paymentSteps.push({
  id,
  label,
  trigger,
  percentage,
  date: trigger === "ON_DATE" ? date! : null,
});

const input = action.input;
if (state.status !== "DRAFT")
  throw new ProposalNotDraftError("Only a draft proposal can be edited");
const step = state.paymentSteps.find((s) => s.id === input.id);
if (!step)
  throw new PaymentStepNotFoundError(`Payment step ${input.id} not found`);
const trigger = input.trigger ?? step.trigger;
const percentage = input.percentage ?? step.percentage;
const date = (input.date !== undefined ? input.date : step.date) ?? null;
checkStep(percentage, trigger, date);
step.label = input.label ?? step.label;
step.trigger = trigger;
step.percentage = percentage;
step.date = trigger === "ON_DATE" ? date : null;

operations.schema:
input RemovePaymentStepInput {
  id: OID!
}

operations.reducer:
if (state.status !== "DRAFT")
  throw new ProposalNotDraftError("Only a draft proposal can be edited");
const index = state.paymentSteps.findIndex((s) => s.id === action.input.id);
if (index === -1)
  throw new PaymentStepNotFoundError(
    `Payment step ${action.input.id} not found`,
  );
state.paymentSteps.splice(index, 1);

operations.schema:
input AddActorInput {
  id: OID!
  code: String!
  name: String!
  description: String
}

operations.reducer:
const { id, code, name, description } = action.input;
if (state.status !== "DRAFT")
  throw new ProposalNotDraftError("Only a draft proposal can be edited");
if (state.actors.some((actor) => actor.id === id))
  throw new DuplicateActorIdError(`Actor ${id} already exists`);
if (state.actors.some((actor) => actor.code === code))
  throw new DuplicateActorCodeError(`Actor code ${code} is already used`);
state.actors.push({ id, code, name, description: description ?? null });

operations.schema:
input UpdateActorInput {
  id: OID!
  code: String
  name: String
  description: String
}

operations.reducer:
const input = action.input;
if (state.status !== "DRAFT")
  throw new ProposalNotDraftError("Only a draft proposal can be edited");
const actor = state.actors.find((item) => item.id === input.id);
if (!actor) throw new ActorNotFoundError(`Actor ${input.id} not found`);
if (
  input.code != null &&
  state.actors.some((a) => a.id !== actor.id && a.code === input.code)
)
  throw new DuplicateActorCodeError(
    `Actor code ${input.code} is already used`,
  );
if (input.code != null) actor.code = input.code;
if (input.name != null) actor.name = input.name;
if (input.description !== undefined) actor.description = input.description;

operations.schema:
input RemoveActorInput {
  id: OID!
}

operations.reducer:
const { id } = action.input;
if (state.status !== "DRAFT")
  throw new ProposalNotDraftError("Only a draft proposal can be edited");
const index = state.actors.findIndex((actor) => actor.id === id);
if (index === -1) throw new ActorNotFoundError(`Actor ${id} not found`);
if (state.useCases.some((useCase) => useCase.actorId === id))
  throw new ActorInUseError(`Actor ${id} is still used by a use case`);
state.actors.splice(index, 1);

const { id, code, actorId, packageId, title, body } = action.input;
if (state.status !== "DRAFT")
  throw new ProposalNotDraftError("Only a draft proposal can be edited");
if (state.useCases.some((useCase) => useCase.id === id))
  throw new DuplicateUseCaseIdError(`Use case ${id} already exists`);
if (state.useCases.some((useCase) => useCase.code === code))
  throw new DuplicateUseCaseCodeError(
    `Use case code ${code} is already used`,
  );
if (!state.actors.some((actor) => actor.id === actorId))
  throw new ActorNotFoundError(`Actor ${actorId} not found`);
if (!state.packages.some((pkg) => pkg.id === packageId))
  throw new PackageNotFoundError(`Package ${packageId} not found`);
state.useCases.push({
  id,
  code,
  actorId,
  packageId,
  title,
  body: body ?? null,
});

const input = action.input;
if (state.status !== "DRAFT")
  throw new ProposalNotDraftError("Only a draft proposal can be edited");
const useCase = state.useCases.find((item) => item.id === input.id);
if (!useCase)
  throw new UseCaseNotFoundError(`Use case ${input.id} not found`);
if (
  input.code != null &&
  state.useCases.some((u) => u.id !== useCase.id && u.code === input.code)
)
  throw new DuplicateUseCaseCodeError(
    `Use case code ${input.code} is already used`,
  );
if (
  input.actorId != null &&
  !state.actors.some((actor) => actor.id === input.actorId)
)
  throw new ActorNotFoundError(`Actor ${input.actorId} not found`);
if (
  input.packageId != null &&
  !state.packages.some((pkg) => pkg.id === input.packageId)
)
  throw new PackageNotFoundError(`Package ${input.packageId} not found`);
if (input.code != null) useCase.code = input.code;
if (input.actorId != null) useCase.actorId = input.actorId;
if (input.packageId != null) useCase.packageId = input.packageId;
if (input.title != null) useCase.title = input.title;
if (input.body !== undefined) useCase.body = input.body;

operations.schema:
input RemoveUseCaseInput {
  id: OID!
}

operations.reducer:
const { id } = action.input;
if (state.status !== "DRAFT")
  throw new ProposalNotDraftError("Only a draft proposal can be edited");
const index = state.useCases.findIndex((useCase) => useCase.id === id);
if (index === -1)
  throw new UseCaseNotFoundError(`Use case ${id} not found`);
state.useCases.splice(index, 1);
